// раскодировать один раз; оттенок волос — по верхней части снимка
function faceOf(id){const F=FACES[id];if(!F)return null;if(!F.px){try{const b=atob(F.g),n=b.length,a=new Uint8Array(n);for(let i=0;i<n;i++)a[i]=b.charCodeAt(i);F.px=a;
    let top=0,k=0;for(let j=0;j<4;j++)for(let i=6;i<18;i++){top+=a[j*F.w+i];k++;}top/=k*255;F.hair=top>0.62?'#8a8074':top>0.45?'#5a4028':'#241a14';
    // края снимка (фон, воротник) плавно уходят в тон щёк — на голове не видно «рамки»
    let m=0,q=0;for(let j=Math.round(F.h*0.35);j<Math.round(F.h*0.75);j++)for(let i=Math.round(F.w*0.25);i<Math.round(F.w*0.75);i++){m+=a[j*F.w+i];q++;}m/=q;F.mean=m;
    for(let j=0;j<F.h;j++)for(let i=0;i<F.w;i++){const x=((i+0.5)/F.w-0.5)/0.47,y=((j+0.5)/F.h-0.54)/0.52,r=Math.sqrt(x*x+y*y),w=Math.max(0,Math.min(1,(1.02-r)/0.3));a[j*F.w+i]=Math.round(m+(a[j*F.w+i]-m)*w);}}catch(_){return null;}}return F;}
